-- Speglar det som lades på databasen 2026-09-16 via apply_migration i sex delar:
--   sy3000_order_code_from_catalogue_part_01  (backup, schema, familj, parametrar)
--   sy3000_order_code_from_catalogue_part_02  (värdelista, rensning av regler)
--   sy3000_order_code_from_catalogue_part_03  (regler 1–20)
--   sy3000_order_code_from_catalogue_part_04  (regler 21–40)
--   sy3000_order_code_from_catalogue_part_05  (regler 41–60)
--   sy3000_order_code_from_catalogue_part_06  (regler 61–72, dokumentkarta, produktraden döpt om)
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts sy3000):
--   regler  72   md5 055f215122e08793c81f45523669025e   villkor 1ac21c6b92eaff3809ad14a9ece85df6
--   värden  81   md5 02a64b159053477d79323f4cdce7099b
--   schema       md5 34bbe0047faabde916cbf682a952beac
-- Verifierat live: /sv/configurator/sy3000 bygger SY5120-5L-01 (nyckelns exempel sida 732) och
-- SY3140-5LOZ-01F (produktraden, sida 748), stoppar SY3000 med DIN-kontakt på underplatta.
--
-- SY: beställnyckeln enligt SMC 5 Port Solenoid Valve SY3000/5000/7000/9000 Series (sida 732 och 748).
-- GENERERAD ur src/lib/catalog/sy.ts -- redigera inte för hand.
--
-- Rättar familjen sy3000, som hade mallen 'SY3000-{size}-{function}-{voltage}-{connection}'
-- med påhittade värden. SMC:s kod är
-- SY{serie}{funktion}{kropp}{pilot}{spole}-{spänning}{anslutning}{ljus}{manöver}-{port}{gänga}-{fäste}-{special}-{ce},
-- t.ex. SY5120-5L-01 (kroppsportad, sida 732) och SY5240-5L (basmonterad,
-- sida 748). Serierna 5000/7000/9000, kropp, extern pilot, strömsparkrets,
-- nio spänningar, 27 elanslutningar (M8 med kabellängd), ljus/spärrdiod,
-- manöver, port och gänga per serie, fästen och -X20/-X90/-X701 fanns inte alls.
--
-- SMC-SY3120-5LOZ döps om till SMC-SY3140-5LOZ-01F (underplatta G 1/8 enligt namnet).

begin;

create schema if not exists backup;
create table if not exists backup.sy3000_before_20260916 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'sy3000'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'sy3000'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'sy3000';

insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
