,{"v":"6","label":"12 V DC"},{"v":"V","label":"6 V DC (inte DIN-kontakt)"},{"v":"S","label":"5 V DC (inte DIN-kontakt)"},{"v":"R","label":"3 V DC (inte DIN-kontakt)"},{"v":"1","label":"100 V AC 50/60 Hz"},{"v":"2","label":"200 V AC 50/60 Hz"},{"v":"3","label":"110 V AC [115 V AC] 50/60 Hz"},{"v":"4","label":"220 V AC [230 V AC] 50/60 Hz"}]},{"id":"entry","step":7,"title_sv":"Elanslutning","title_en":"Electrical entry","required":true,"type":"single_select","options":[{"v":"G","label":"Grommet, kabel 300 mm"},{"v":"H","label":"Grommet, kabel 600 mm"},{"v":"L","label":"L-plugg med kabel 300 mm"},{"v":"LN","label":"L-plugg utan kabel (två stift)"},{"v":"LO","label":"L-plugg utan kontakt"},{"v":"M","label":"M-plugg med kabel 300 mm"},{"v":"MN","label":"M-plugg utan kabel (två stift)"},{"v":"MO","label":"M-plugg utan kontakt"},{"v":"D","label":"DIN-kontakt med kontaktdon (IP65; DC 24/12 V)"},{"v":"DO","label":"DIN-kontakt utan kontaktdon (IP65; DC 24/12 V)"},{"v":"Y","label":"DIN EN 175301-803C med kontaktdon (IP65; DC 24/12 V)"},{"v":"YO","label":"DIN EN 175301-803C utan kontaktdon (IP65; DC 24/12 V)"},{"v":"WO","label":"M8-kontakt utan kabel (IP65; bara DC)"},{"v":"W1","label":"M8-kontakt med kabel 300 mm (IP65; bara DC)"},{"v":"W2","label":"M8-kontakt med kabel 500 mm (IP65; bara DC)"},{"v":"W3","label":"M8-kontakt med kabel 1000 mm (IP65; bara DC)"},{"v":"W4","label":"M8-kontakt med kabel 2000 mm (IP65; bara DC)"},{"v":"W5","label":"M8-kontakt med kabel 3000 mm (IP65; bara DC)"},{"v":"W6","label":"M8-kontakt med kabel 4000 mm (IP65; bara DC)"},{"v":"W7","label":"M8-kontakt med kabel 5000 mm (IP65; bara DC)"},{"v":"WA1","label":"M8-kontakt IEC 60947-2 med kabel 300 mm (IP65; bara DC)"},{"v":"WA2","label":"M8-kontakt IEC 60947-2 med kabel 500 mm (IP65; bara DC)"},{"v":"WA3","label":"M8-kontakt IEC 60947-2 med kabel 1000 mm (IP65; bara DC)"},{"v":"WA4","label":"M8-kontakt IEC 60947-2 med kabel 2000 mm (IP65; bara DC)"},{"v":"WA5","label":"M8-kontakt IEC 60947-2 med kabel 3000 mm (IP65; bara DC)"},{"v":"WA6","label":"M8-kontakt IEC 60947-2 med kabel 4000 mm (IP65; bara DC)"},{"v":"WA7","label":"M8-kontakt IEC 60947-2 med kabel 5000 mm (IP65; bara DC)"}]},{"id":"light","step":8,"title_sv":"Ljus/spärrdiod","title_en":"Light/surge voltage suppressor","required":false,"type":"single_select","options":[{"v":"S","label":"Spärrdiod (bara DC; DIN: opolär)"},{"v":"Z","label":"Ljus och spärrdiod (DIN: opolär)"},{"v":"R","label":"Spärrdiod, opolär (bara DC; inte DIN)"},{"v":"U","label":"Ljus och spärrdiod, opolär (bara DC; inte DIN)"}]},{"id":"override","step":9,"title_sv":"Manuell manöver (standard är olåst tryckknapp)","title_en":"Manual override (non-locking push type is standard)","required":false,"type":"single_select","options":[{"v":"D","label":"Låsbar manöver, spårskruv (tryck och vrid)"},{"v":"E","label":"Låsbar manöver, spak (tryck och vrid)"}]},{"id":"port","step":10,"title_sv":"Portstorlek (kroppsportad) eller underplatta (basmonterad)","title_en":"Port size (body ported) or sub-plate (base mounted)","required":false,"type":"single_select","options":[{"v":"M5","label":"M5 x 0,8 kroppsportad (SY3000; bara Rc-utförandet)"},{"v":"01","label":"1/8: kroppsportad SY5000, underplatta SY3000"},{"v":"02","label":"1/4: kroppsportad SY7000/9000, underplatta SY5000/7000"},{"v":"03","label":"3/8: kroppsportad SY9000, underplatta SY7000/9000"},{"v":"04","label":"1/2: underplatta SY9000"},{"v":"C4","label":"Snabbkoppling ø4 (SY3000/5000)"},{"v":"C6","label":"Snabbkoppling ø6 (SY3000/5000)"},{"v":"C8","label":"Snabbkoppling ø8 (SY5000/7000/9000)"},{"v":"C10","label":"Snabbkoppling ø10 (SY7000/9000)"},{"v":"C12","label":"Snabbkoppling ø12 (SY9000)"},{"v":"N3","label":"Snabbkoppling ø5/32\" (SY3000/5000)"},{"v":"N7","label":"Snabbkoppling ø1/4\" (SY3000/5000)"},{"v":"N9","label":"Snabbkoppling ø5/16\" (SY5000/7000/9000)"},{"v":"N11","label":"Snabbkoppling ø3/8\" (SY7000/9000)"}]},{"id":"thread","step":11,"title_sv":"Gängtyp (standard är Rc)","title_en":"Thread type (Rc is standard)","required":false,"type":"single_select","options":[{"v":"F","label":"G-gänga (standard är Rc)"},{"v":"N","label":"NPT-gänga"},{"v":"T","label":"NPTF-gänga"}]},{"id":"bracket","step":12,"title_sv":"Fäste","title_en":"Bracket","required":false,"type":"single_select","options":[{"v":"F1","label":"Fotfäste (bara 2-läges enkel, kroppsportad; inte SY9000)"},{"v":"F2","label":"Sidofäste (kroppsportad; inte SY9000)"}]},{"id":"mto","step":13,"title_sv":"Specialutförande","title_en":"Made to order","required":false,"type":"single_select","options":[{"v":"X20","label":"-X20 Extern pilot, kroppsportad (inte SY9000)"},{"v":"X90","label":"-X90 Huvudventil i fluorgummi"},{"v":"X701","label":"-X701 4-läges dubbel 3-portsventil (funktion A/B/C, SY5000/7000)"}]},{"id":"ce","step":14,"title_sv":"CE/UKCA-märkning","title_en":"CE/UKCA marking","required":false,"type":"single_select","options":[{"v":"Q","label":"CE/UKCA-märkt (AC bara med DIN-kontakt)"}]}]}'::jsonb,
        'SMC SY3000/5000/7000/9000 5-portsventil, enkelventil', 'SMC SY3000/5000/7000/9000 5 port solenoid valve, single unit', 'valve')
