update configurator_families set
  title = '5-portsventil SY3000/5000/7000/9000, enkelventil kroppsportad eller basmonterad',
  description = 'SMC SY3000/5000/7000/9000 5 port solenoid valve, single unit: 2-position single/double and 3-position, body ported (M5–3/8 or One-touch fittings) or base mounted with sub-plate (1/8–1/2), DC or AC, grommet, plug, DIN or M8 connector, power saving circuit, -X20/-X90/-X701.',
  stroke_min_mm = null,
  stroke_max_mm = null,
  order_code_template = 'SY{series}{actuation}{body}{pilot}{coil}-{voltage}{entry}{light}{override}-{port}{thread}-{bracket}-{mto}-{ce}',
  rules_schema_id = 'SCHEMA-SY3000-V1'
where slug = 'sy3000';


