       as r(param_key text, code text, label text, sort_order int)
join configurator_params p on p.param_key = r.param_key
join configurator_families f on f.id = p.family_id and f.slug = 'sy3000';

delete from config_rules where schema_id = 'SCHEMA-SY3000-V1';


