insert into knowledge_doc_families (source_file, family_slug, doc_title)
values ('smc-kat-sy3000.pdf', 'sy3000', 'SMC — SMC 5 Port Solenoid Valve SY3000/5000/7000/9000 Series')
on conflict (source_file, family_slug) do update set doc_title = excluded.doc_title;


update products set
  sku = 'SMC-SY3140-5LOZ-01F',
  name = 'SY3140 5/2 monostabil, underplatta G 1/8',
  description = '5 port solenoid valve SY3000, 2-position single (monostable), base mounted on a sub-plate G 1/8, 24 V DC, L plug connector without connector, with light/surge voltage suppressor. Order code SY3140-5LOZ-01F (catalogue page 748).'
where sku = 'SMC-SY3120-5LOZ';

update product_specs s set value = '5/2 monostabil (2-läges enkel magnet)'
from products p where s.product_id = p.id and p.sku = 'SMC-SY3140-5LOZ-01F' and s.key = 'function';

update product_specs s set value = '7'
from products p where s.product_id = p.id and p.sku = 'SMC-SY3140-5LOZ-01F' and s.key = 'max_pressure';

insert into product_specs (product_id, key, value)
select p.id, x.key, x.value
from products p
cross join lateral (values
  ('series', 'SY3000'),
  ('mounting', 'Basmonterad på underplatta G 1/8'),
  ('min_pressure_mpa', '0.15'),
  ('temp_range', '-10 to +50'),
  ('max_frequency_hz', '10'),
  ('power_w', '0.35 (med ljus 0.4)'),
  ('order_code_example', 'SY3140-5LOZ-01F'),
  ('catalogue', 'SMC SY3000/5000/7000/9000, How to Order sida 732 (kroppsportad) och 748 (basmonterad), data sida 733')
) as x(key, value)
where p.sku = 'SMC-SY3140-5LOZ-01F'
  and not exists (select 1 from product_specs y where y.product_id = p.id and y.key = x.key);


commit;

